<script type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"ProfessionalService","@id":"https://marylandinsuranceappraiser.com/#business","name":"Maryland Insurance Appraiser","url":"https://marylandinsuranceappraiser.com/","telephone":"+1 (844) 537-1427","email":"info@marylandinsuranceappraiser.com","logo":{"@type":"ImageObject","@id":"https://marylandinsuranceappraiser.com/#logo","url":"https://marylandinsuranceappraiser.com/favicon-512.png","width":512,"height":512,"caption":"Maryland Insurance Appraiser"},"image":{"@id":"https://marylandinsuranceappraiser.com/#logo"},"address":{"@type":"PostalAddress","addressRegion":"MD","addressCountry":"US"},"contactPoint":[{"@type":"ContactPoint","telephone":"+1 (844) 537-1427","email":"info@marylandinsuranceappraiser.com","contactType":"customer service","areaServed":"US-MD","availableLanguage":"en"}],"slogan":"Independent valuation for disputed property claims","description":"Independent insurance appraisal, carrier estimate review and neutral umpire services for disputed property claims in every Maryland county and Baltimore City.","areaServed":[{"@type":"State","name":"Maryland"},{"@type":"City","name":"Baltimore"},{"@type":"City","name":"Towson"},{"@type":"City","name":"Ellicott City"},{"@type":"City","name":"Annapolis"},{"@type":"City","name":"Frederick"},{"@type":"City","name":"Rockville"},{"@type":"City","name":"Bowie"},{"@type":"City","name":"Waldorf"},{"@type":"City","name":"Hagerstown"},{"@type":"City","name":"Cumberland"},{"@type":"City","name":"Salisbury"},{"@type":"City","name":"Ocean City"}],"hasOfferCatalog":{"@type":"OfferCatalog","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Demand Representation","url":"https://marylandinsuranceappraiser.com/property-claim-services/appraisal-demand-representation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Home Insurance Appraisal","url":"https://marylandinsuranceappraiser.com/property-claim-services/home-insurance-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Appraisal","url":"https://marylandinsuranceappraiser.com/property-claim-services/commercial-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://marylandinsuranceappraiser.com/property-claim-services/roof-hail-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Windstorm & Tornado Appraisal","url":"https://marylandinsuranceappraiser.com/property-claim-services/windstorm-tornado-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Hurricane & Nor’easter Appraisal","url":"https://marylandinsuranceappraiser.com/property-claim-services/hurricane-noreaster-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Appraisal","url":"https://marylandinsuranceappraiser.com/property-claim-services/water-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://marylandinsuranceappraiser.com/property-claim-services/fire-smoke-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Snow, Ice Dam & Freeze Appraisal","url":"https://marylandinsuranceappraiser.com/property-claim-services/snow-ice-dam-freeze-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tree Impact Claim Appraisal","url":"https://marylandinsuranceappraiser.com/property-claim-services/tree-impact-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Carrier Estimate Review","url":"https://marylandinsuranceappraiser.com/property-claim-services/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Neutral Umpire Services","url":"https://marylandinsuranceappraiser.com/property-claim-services/neutral-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Umpire","Property claim valuation","Hurricane deductibles","Ice dam claims","Rowhouse roofing"],"priceRange":"$$","openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://marylandinsuranceappraiser.com/#website","url":"https://marylandinsuranceappraiser.com/","name":"Maryland Insurance Appraiser","publisher":{"@id":"https://marylandinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://marylandinsuranceappraiser.com/common-questions/#webpage","url":"https://marylandinsuranceappraiser.com/common-questions/","name":"Insurance Appraisal Questions | Maryland FAQ by Topic","description":"Answers to common Maryland insurance appraisal questions, grouped by topic: basics, fees, deadlines, the MIA and storm, water and winter claims.","inLanguage":"en-US","isPartOf":{"@id":"https://marylandinsuranceappraiser.com/#website"},"about":{"@id":"https://marylandinsuranceappraiser.com/#business"},"publisher":{"@id":"https://marylandinsuranceappraiser.com/#business"},"dateModified":"2026-11-12","primaryImageOfPage":{"@type":"ImageObject","@id":"https://marylandinsuranceappraiser.com/common-questions/#primaryimage","url":"https://marylandinsuranceappraiser.com/assets/img/photos/rowhouse-street.webp","width":1024,"height":768},"breadcrumb":{"@id":"https://marylandinsuranceappraiser.com/common-questions/#breadcrumb"},"mainEntity":{"@id":"https://marylandinsuranceappraiser.com/common-questions/#faq"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://marylandinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Common questions","item":"https://marylandinsuranceappraiser.com/common-questions/"}],"@id":"https://marylandinsuranceappraiser.com/common-questions/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is the appraisal clause in a Maryland property policy?","acceptedAnswer":{"@type":"Answer","text":"It is a section of most homeowners and commercial property policies that lets either you or your insurer resolve a disagreement over the amount of a covered loss outside of court. Each side names an appraiser, the two appraisers pick an umpire, and an award signed by any two of the three generally sets the amount. The exact wording varies, so read your own policy."}},{"@type":"Question","name":"Does appraisal decide whether my claim is covered?","acceptedAnswer":{"@type":"Answer","text":"Generally, no. Appraisal is designed to decide how much the damage costs, not whether the policy covers it. If your insurer has denied the claim on coverage grounds, talk with a Maryland attorney or consider a complaint to the Maryland Insurance Administration."}},{"@type":"Question","name":"Is the appraisal award binding?","acceptedAnswer":{"@type":"Answer","text":"Most policy forms treat a signed award as setting the amount of loss, and courts generally give awards considerable weight. Awards can sometimes be challenged, for example over fraud, bias or a panel deciding issues outside its authority. Ask an attorney if you are concerned about a specific award."}},{"@type":"Question","name":"Can my insurer demand appraisal instead of me?","acceptedAnswer":{"@type":"Answer","text":"Yes, under most appraisal clauses either party can invoke it. If your insurer sends a demand, you will usually need to name your own appraiser within the time the policy sets. Reading the demand carefully and responding on time protects your position."}},{"@type":"Question","name":"Is Maryland Insurance Appraiser a public adjuster or law firm?","acceptedAnswer":{"@type":"Answer","text":"No. Maryland Insurance Appraiser is an independent appraisal firm that handles appraisal representation, estimate review and umpire work. We don’t give legal advice or negotiate coverage, and we will tell you when a question needs an attorney."}},{"@type":"Question","name":"Who pays for the appraisers and the umpire?","acceptedAnswer":{"@type":"Answer","text":"Under most policies, each side pays its own appraiser and the umpire’s fee is split equally. Other shared costs, such as an engineer the panel agrees to bring in, are often divided the same way. Check your policy, because some forms word this differently."}},{"@type":"Question","name":"How are independent appraisers usually paid?","acceptedAnswer":{"@type":"Answer","text":"Common arrangements include hourly rates, a flat fee or a fee tied to the size of the claim. Whatever the structure, get it in writing before work starts. Be cautious about any arrangement that could make the appraiser look less than disinterested."}},{"@type":"Question","name":"Is appraisal worth it for a small claim?","acceptedAnswer":{"@type":"Answer","text":"It depends on the gap and the costs. If the difference between estimates is only a few thousand dollars, appraiser and umpire fees may eat most of it. A quick estimate review can help you decide before you commit."}},{"@type":"Question","name":"Can I recover my appraisal costs from the insurer?","acceptedAnswer":{"@type":"Answer","text":"Appraisal costs are usually your responsibility under the policy, even if the award is higher than the insurer’s estimate. Whether any expenses can be recovered in a separate legal claim is a question for a Maryland attorney."}},{"@type":"Question","name":"How long does an appraisal take?","acceptedAnswer":{"@type":"Answer","text":"Many residential appraisals wrap up within a few weeks to a few months, depending on how quickly appraisers are named, how complex the damage is and whether the umpire is needed. Large commercial or condominium claims can take longer. Good documentation is the biggest factor you control."}},{"@type":"Question","name":"How soon must I name my appraiser?","acceptedAnswer":{"@type":"Answer","text":"Many policies give each side about 20 days after the written demand. Your policy may use a different period, so check the wording and calendar the date as soon as a demand is sent or received."}},{"@type":"Question","name":"Does appraisal pause the deadline to sue my insurer?","acceptedAnswer":{"@type":"Answer","text":"Don’t assume so. Maryland’s general contract limitations period is three years, and Maryland law generally doesn’t let property policies shorten it, but when that clock starts can be disputed. Ask an attorney about your dates before relying on appraisal to protect them."}},{"@type":"Question","name":"Is there a deadline to invoke appraisal?","acceptedAnswer":{"@type":"Answer","text":"Some policies don’t set one, while others tie appraisal to other claim steps. Waiting too long or acting inconsistently with appraisal can create arguments that the right was waived. It is usually best to decide once the insurer’s final estimate is clear."}},{"@type":"Question","name":"When is recoverable depreciation paid after an award?","acceptedAnswer":{"@type":"Answer","text":"Usually after repairs are completed and documented. Many policies set a time window for completing repairs to collect replacement cost, so read that section and keep invoices and photos of the finished work."}},{"@type":"Question","name":"Should I file a complaint with the Maryland Insurance Administration or demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"They do different jobs. An MIA complaint addresses how the insurer handled your claim, such as delays or unexplained decisions, while appraisal sets the dollar amount of a covered loss. Some people use both; an attorney can help if legal remedies are involved."}},{"@type":"Question","name":"Can I keep talking to my adjuster during appraisal?","acceptedAnswer":{"@type":"Answer","text":"Yes, and you should keep communication professional and in writing where possible. Your appraiser handles the valuation discussion with the insurer’s appraiser, but the adjuster still manages payments, coverage letters and other claim steps."}},{"@type":"Question","name":"What if my insurer refuses to take part in appraisal?","acceptedAnswer":{"@type":"Answer","text":"If the policy contains an appraisal clause, refusal raises legal questions about enforcing the contract. Many policies allow a court to appoint an umpire, and courts can be asked to compel appraisal in some situations. That is a matter for a Maryland attorney."}},{"@type":"Question","name":"What if I’m insured through the Maryland Joint Insurance Association?","acceptedAnswer":{"@type":"Answer","text":"MJIA policies have their own policy forms, so read the conditions section to see what dispute resolution options apply. The same basic principles about documenting the loss and comparing estimates still help."}},{"@type":"Question","name":"Can appraisal resolve a hurricane deductible dispute?","acceptedAnswer":{"@type":"Answer","text":"Appraisal can set the amount of damage, but whether a percentage hurricane or named-storm deductible was triggered is usually a coverage question about policy definitions. If the trigger is disputed, ask an attorney or the MIA alongside any appraisal of the amount."}},{"@type":"Question","name":"Does appraisal help with ice dam claims in Western Maryland?","acceptedAnswer":{"@type":"Answer","text":"It can, when the insurer accepts that interior water damage from an ice dam is covered but undervalues the repair. Disputes over whether long-term seepage or wear is excluded are coverage questions rather than appraisal questions."}},{"@type":"Question","name":"My insurer says the storm damage is old wear and tear. Can appraisal fix that?","acceptedAnswer":{"@type":"Answer","text":"Whether damage was caused by the storm is sometimes treated as part of the amount of loss and sometimes as coverage, depending on the policy and the facts. Because Maryland law on this point can turn on details, get legal advice if causation is the main dispute."}},{"@type":"Question","name":"Is flood damage handled through my homeowners appraisal clause?","acceptedAnswer":{"@type":"Answer","text":"Usually not. Standard homeowners policies typically exclude flood, and flood insurance through the NFIP or a private carrier has its own dispute procedures. Tidal or stream flooding claims should be checked against the separate flood policy."}}],"@id":"https://marylandinsuranceappraiser.com/common-questions/#faq"}]}</script>
</head>
